import {cBusFiles} from './c-sensor-examples.js';
export const PIN_CONFIG_MARKER='// CircuitForge pin configuration v1';
export const GPIO_FUNCTIONS=[['unused','Kullanılmıyor'],['input','GPIO · Giriş'],['pullup','GPIO · Giriş / pull-up'],['pulldown','GPIO · Giriş / pull-down'],['output','GPIO · Çıkış'],['open_drain','GPIO · Açık drenaj'],['exti_rising','EXTI · Yükselen kenar'],['exti_falling','EXTI · Düşen kenar'],['exti_both','EXTI · İki kenar']];
