 const tim3={PA6:1,PA7:2,PB0:3,PB1:4};if(tim3[pin])add('TIM3_CH'+tim3[pin],2);
 if(/^PA(8|9|10|11)$/.test(pin))add('TIM1_CH'+(+pin.slice(2)-7),1);
